bad_plan <- plan; bad_plan$study_id <- "wrong-study"; analysis_plan_write(bad_plan, analysis_plan_path(study_dir)); bad_plan_result <- finalize_statistical_review(study_dir, review_path, review_path, allow_unresolved = TRUE)
stopifnot(bad_plan_result$published, !bad_plan_result$ready_for_final_signature, any(bad_plan_result$issues$issue_id == "PLAN-SCHEMA-STUDY-ID"))
blocked_review <- read_statistical_review(review_path); stopifnot(!identical(as.character(blocked_review$metadata$finalization_status), "ready_for_final_signature"), all(vapply(blocked_review$metadata[hash_names], function(x) !nzchar(as.character(x)), logical(1))), any(grepl("PLAN-SCHEMA-STUDY-ID", statistical_review_section_lines(blocked_review, statistical_review_required_headings()[[7L]]), fixed = TRUE)))
stopifnot(inherits(try(approve_and_generate_analysis(study_dir, project_dir, "Synthetic Reviewer"), silent = TRUE), "try-error"))
analysis_plan_write(plan, analysis_plan_path(study_dir)); restored <- finalize_statistical_review(study_dir, review_path, review_path, allow_unresolved = TRUE); stopifnot(restored$published, restored$ready_for_final_signature, restored$analysis_count == 1L)
chain <- approve_and_generate_analysis(study_dir, project_dir, "Synthetic Reviewer"); stopifnot(identical(chain$review$metadata$review_status, "approved"), file.exists(analysis_contract_path(study_dir)), file.exists(file.path(study_dir, "analysis", "r", "MMRM-01.R")), file.exists(file.path(study_dir, "analysis", "r", "run_all_mmrm.R")), file.exists(file.path(study_dir, "analysis", "sas", "MMRM-01_template.sas")))
writeLines("trap_response: LEGACY_TRAP_VALUE", file.path(study_dir, "statistician-review", "endpoint-mapping.yaml"), useBytes = TRUE); writeLines("LEGACY_SPEC_TRAP_VALUE", file.path(study_dir, "statistician-review", "analysis-specification.md"), useBytes = TRUE)
