legacy_blocked_review <- read_statistical_review(review_path); stopifnot(!identical(as.character(legacy_blocked_review$metadata$finalization_status), "ready_for_final_signature"), !identical(as.character(legacy_blocked_review$metadata$review_status), "approved"))
